import React from 'react';

import { useNavigate } from 'react-router-dom';

import PageLoader from '@components/PageLoader';
import { declOfNum } from '@helpers/formatHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import PohList from '@ui-kit/List';

import { getFriendsData } from '../@services/user.services';
import { IOneFriend } from '../@types/user.types';

const FriendsList: React.FC = () => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IOneFriend[]>([]);
  const navigate = useNavigate();

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const dt = await getFriendsData();
        setData(dt);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, []);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  if (data.length === 0)
    return <PohAlert variant={AlertVariant.Info}>Похоже тут никого нет. Все впереди!</PohAlert>;

  return (
    <PohList
      data={data
        .filter((u) => u.statistic)
        .map((user) => {
          return {
            key: user.id,
            onClick: () => navigate(`/user/${user.id}`),
            action: true,
            children: user.statistic && (
              <div className="w-100">
                <div className="d-flex w-100">
                  <PohAva
                    width={48}
                    alt={[user.name, user.surname].join(' ')}
                    src={user.photo}
                    colorize
                    className="me-2"
                  />
                  <div className="flex-grow-1">
                    <div>
                      {user.name} {user.surname}
                    </div>

                    <small className="d-block text-info">
                      {user.statistic.hikingCount}{' '}
                      {declOfNum(user.statistic.hikingCount, [
                        'совместный поход',
                        'совместных похода',
                        'совместных походов',
                      ])}
                    </small>
                    <small className="d-block text-muted">
                      Первый совместный поход: {user.statistic.hikingFirstDate.toLocaleDateString()}
                    </small>
                  </div>
                </div>
              </div>
            ),
          };
        })}
    />
  );
};

export default FriendsList;
